import test from 'node:test';import assert from 'node:assert/strict';
import {HttpLibrary,LocalLibrary,validateConfig} from '../src/adapters.js';
import {cleanPreferences,filterTracks,moveItem,validateTrack,escapeHTML,formatTime,playlistExport} from '../src/model.js';
import {demoTracks,createDemoAudio} from '../src/demo.js';
const config=validateConfig({contract_version:'resonant-player/config/1',mode:'http',apiBase:'/api/',mediaOrigins:['https://media.example.com']},'https://player.example.com/');
const response=value=>({ok:true,json:async()=>value});
const catalog=(tracks=demoTracks,rest={})=>({contract_version:'resonant-player/library/1',revision:'r1',tracks,next_cursor:null,...rest});
const capability=(rest={})=>({contract_version:'resonant-player/playback-session/1',track_id:demoTracks[0].id,source_version:demoTracks[0].sourceVersion,url:'https://media.example.com/audio?signature=example',expires_at:new Date(Date.now()+60000).toISOString(),...rest});
test('config rejects unsafe/cross-origin APIs and implicit media origins',()=>{for(const apiBase of ['https://other.example/api/','/api','/api/?key=secret'])assert.throws(()=>validateConfig({contract_version:'resonant-player/config/1',mode:'http',apiBase},'https://player.example.com/'));assert.throws(()=>validateConfig({contract_version:'resonant-player/config/1',mode:'http',mediaOrigins:['*']},'https://player.example.com/'));});
test('catalog validates pagination, revision and public fields',async()=>{
  let calls=0;const api=new HttpLibrary(config,async()=>response(++calls===1?catalog([{...demoTracks[0],private_path:'/secret',url:'secret'}],{next_cursor:'page-2'}):catalog([demoTracks[1]])));
  const tracks=await api.listTracks();assert.equal(tracks.length,2);assert.equal(tracks[0].kind,'cloud');assert.equal(tracks[0].url,undefined);assert.equal(tracks[0].private_path,undefined);
});
test('catalog rejects duplicate identities and revision drift',async()=>{const dup=new HttpLibrary(config,async()=>response(catalog([demoTracks[0],demoTracks[0]])));await assert.rejects(dup.listTracks(),/duplicate/);let n=0;const drift=new HttpLibrary(config,async()=>response(catalog([demoTracks[n++]],{revision:`r${n}`,next_cursor:'next'})));await assert.rejects(drift.listTracks(),/changed/);});
test('catalog rejects repeated cursors instead of looping',async()=>{let n=0;const api=new HttpLibrary(config,async()=>response(catalog([demoTracks[n++]],{next_cursor:'same'})));await assert.rejects(api.listTracks(),/cursor/);assert.equal(n,2);});
test('playback request contains identity and position, no tenant/object key',async()=>{
  let sent;const api=new HttpLibrary(config,async(url,options)=>{sent=options;assert.equal(url.pathname,'/api/v1/playback-sessions');return response(capability());});
  const result=await api.resolvePlayback(demoTracks[0],{position:19});assert.equal(result.expiresAt> Date.now(),true);const body=JSON.parse(sent.body);assert.equal(body.position_seconds,19);assert.equal(body.tenant_id,undefined);assert.equal(sent.credentials,'same-origin');assert.equal(sent.redirect,'error');
});
test('playback rejects wrong origins, protocols, expiry and source identity',async()=>{for(const override of [{url:'https://evil.example.com/audio'},{url:'javascript:alert(1)'},{expires_at:'bad'},{expires_at:new Date(Date.now()-1).toISOString()},{source_version:'other'},{track_id:'other'},{url:'https://user:secret@media.example.com/audio'}]){const api=new HttpLibrary(config,async()=>response(capability(override)));await assert.rejects(api.resolvePlayback(demoTracks[0]),/invalid playback session/);}});
test('service errors redact server response and do not persist signed capabilities',async()=>{const api=new HttpLibrary(config,async()=>({ok:false,status:401,json:async()=>({stack:'secret'})}));await assert.rejects(api.listTracks(),/session has expired/);});
test('aborted fetch stays an abort rather than a misleading network message',async()=>{const api=new HttpLibrary(config,async()=>{throw Object.assign(new Error('abort'),{name:'AbortError'});});await assert.rejects(api.listTracks(),{name:'AbortError'});});
test('invalid evidence authorities are rejected and missing descriptors remain absent',()=>{assert.throws(()=>validateTrack({...demoTracks[0],evidence:[{field:'bpm',value:'120',source:'x',authority:'fact'}]}),/evidence/);assert.deepEqual(validateTrack({...demoTracks[0],evidence:undefined}).evidence,[]);});
test('corrupt preferences recover and arbitrary data never survives serialization',()=>{const p=cleanPreferences({volume:2,favorites:['id',null,'../secret','id'],playlists:[{id:'p1',name:'  ',trackIds:[]},{id:'p2',name:'test',trackIds:['id'],url:'secret'}],url:'secret'});assert.equal(p.volume,1);assert.deepEqual(p.favorites,['id']);assert.equal(p.playlists.length,1);assert.ok(!JSON.stringify(p).includes('secret'));assert.equal(cleanPreferences(null).volume,0.65);});
test('search, favorites and playlist order combine without mutating catalog',()=>{const original=JSON.stringify(demoTracks);assert.equal(filterTracks(demoTracks,{search:'resonant first'}).length,1);assert.deepEqual(filterTracks(demoTracks,{ids:['demo-3','demo-1'],sort:'playlist'}).map(t=>t.id),['demo-3','demo-1']);assert.equal(filterTracks(demoTracks,{favorites:[]}).length,0);assert.equal(JSON.stringify(demoTracks),original);});
test('safe display handles untrusted strings and unknown duration',()=>{assert.equal(escapeHTML('<img onerror="x">'),'&lt;img onerror=&quot;x&quot;&gt;');assert.equal(formatTime(null),'—');assert.equal(formatTime(125),'2:05');assert.deepEqual(moveItem(['a','b'],0,4),['a','b']);});
test('generated fixture is actual bounded PCM with truthful duration',async()=>{const blob=createDemoAudio(0),view=new DataView(await blob.arrayBuffer());assert.equal(blob.type,'audio/wav');assert.equal(view.getUint32(24,true),16000);assert.equal((blob.size-44)/32000,demoTracks[0].duration);assert.equal(view.getUint16(22,true),1);});
test('local import rejects unsupported names and oversized files before probing',async()=>{const lib=new LocalLibrary();lib.db={};await assert.rejects(lib.importFile({name:'note.html',size:4}),/Choose/);await assert.rejects(lib.importFile({name:'large.mp3',size:600*1024*1024}),/512 MB/);});
test('playlist export preserves order and excludes private fields and capabilities',()=>{const tracks=demoTracks.map(t=>({...t,url:'bearer-secret',path:'/private/audio.wav',credentials:'secret'}));const result=playlistExport({name:'Saved',trackIds:['demo-2','demo-1']},tracks);assert.deepEqual(result.tracks.map(t=>t.id),['demo-2','demo-1']);assert.equal(result.contract_version,'resonant-player/playlist-export/1');assert.ok(!JSON.stringify(result).includes('secret'));assert.ok(!JSON.stringify(result).includes('/private'));});
